/* The Rift Convergence — Story Bible client script
 * 1. Gives every searchable passage a stable id (so search results can jump to it).
 * 2. Converts explicit keyword marks written as [[Term]] or [[Term|shown text]].
 * 3. Auto-highlights every dictionary title and alias (the dictionary is generated by Jekyll
 *    from the entry files, so new uploads are picked up automatically).
 * 4. "Ask the Story Bible" search across all pages.
 * 5. Return-to-reading position when a utility panel closes.
 */
(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s);
const readJSON=id=>{try{return JSON.parse($('#'+id).textContent)}catch(e){console.warn('Story Bible: could not read',id,e);return []}};
const dictionary=readJSON('lore-dictionary');
const sitePages=readJSON('lore-pages');
const main=$('main');
const content=$('.page-content');
const norm=s=>s.replace(/\s+/g,' ').trim();
const escapeRe=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');

/* ---------- 1. Passage ids (must run before any DOM changes) ---------- */
const BLOCKS='h2,h3,h4,p,li,tr,blockquote,pre';
function eachPassage(root,fn){
  [...root.querySelectorAll(BLOCKS)].forEach((el,i)=>{
    if(/^H[234]$/.test(el.tagName)){fn(el,i,true);return;}
    const text=norm(el.textContent||'');
    if(text.length<35||text.length>9000)return;
    if(!el.id)el.id='ref-'+i;
    fn(el,i,false,text);
  });
}
if(content)eachPassage(content,()=>{});
if(location.hash.startsWith('#ref-')){const t=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(t)requestAnimationFrame(()=>t.scrollIntoView());}

/* ---------- Dictionary lookup ---------- */
const termMap=new Map();
for(const e of dictionary){
  const aliases=Array.isArray(e.aliases)?e.aliases:(e.aliases?String(e.aliases).split(','):[]);
  for(const name of [e.title,...aliases]){
    const key=String(name||'').trim().toLowerCase();
    if(key&&!termMap.has(key))termMap.set(key,e);
  }
}
const lookup=name=>{const k=norm(name).toLowerCase();return termMap.get(k)||termMap.get(k.replace(/^the /,''))||null;};
const currentEntry=content&&content.dataset.entry;

function makeMark(text,entry,explicit){
  const a=document.createElement('a');
  a.className='lore-mark';a.textContent=text;
  if(explicit)a.dataset.explicit='';
  if(entry){
    a.dataset.category=entry.category;a.dataset.entry=entry.slug;
    a.href='#lore-definition-'+entry.slug;
    a.title=entry.title+(entry.summary?' — '+entry.summary:'')+' (click for definition)';
  }else{
    a.classList.add('lore-missing');a.setAttribute('role','note');a.tabIndex=0;
    a.title='“'+text+'” is marked as a keyword but has no dictionary entry yet. Upload a file named after it to create one.';
  }
  return a;
}
const SKIP='script,style,textarea,input,button,select,option,code,pre,.lore-toolbar,.lore-mark,#lore-directory,#bible-assistant';

/* ---------- 2. Explicit [[Term]] marks ---------- */
const explicitRe=/\[\[([^\[\]|]+?)(?:\|([^\[\]]+?))?\]\]/g;
if(content){
  const walker=document.createTreeWalker(content,NodeFilter.SHOW_TEXT,{acceptNode(n){
    if(!n.nodeValue.includes('[['))return NodeFilter.FILTER_REJECT;
    const p=n.parentElement;
    if(!p||p.closest('script,style,textarea,code,pre'))return NodeFilter.FILTER_REJECT;
    return NodeFilter.FILTER_ACCEPT;}});
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){
    const text=node.nodeValue,frag=document.createDocumentFragment();
    const inHeading=!!node.parentElement.closest('h1,h2,h3,h4,h5,h6,a');
    let last=0,m;explicitRe.lastIndex=0;
    while((m=explicitRe.exec(text))){
      if(m.index>last)frag.append(text.slice(last,m.index));
      const term=m[1].trim(),shown=(m[2]||m[1]).trim();
      // Headings and existing links keep plain text (headings are never highlighted).
      frag.append(inHeading?document.createTextNode(shown):makeMark(shown,lookup(term),true));
      last=explicitRe.lastIndex;
    }
    if(last<text.length)frag.append(text.slice(last));
    node.replaceWith(frag);
  }
}

/* ---------- 3. Automatic highlighting of every known title / alias ---------- */
const names=[...termMap.keys()].sort((a,b)=>b.length-a.length);
if(content&&names.length){
  const re=new RegExp('\\b(?:'+names.map(escapeRe).join('|')+')\\b','gi');
  const walker=document.createTreeWalker(content,NodeFilter.SHOW_TEXT,{acceptNode(n){
    if(!n.nodeValue.trim())return NodeFilter.FILTER_REJECT;
    re.lastIndex=0;if(!re.test(n.nodeValue))return NodeFilter.FILTER_REJECT;
    const p=n.parentElement;
    if(!p||p.closest(SKIP+',a,h1,h2,h3,h4,h5,h6'))return NodeFilter.FILTER_REJECT;
    return NodeFilter.FILTER_ACCEPT;}});
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){
    const text=node.nodeValue,frag=document.createDocumentFragment();
    let last=0,m;re.lastIndex=0;
    while((m=re.exec(text))){
      if(m.index>last)frag.append(text.slice(last,m.index));
      frag.append(makeMark(m[0],lookup(m[0]),false));
      last=re.lastIndex;
    }
    if(last<text.length)frag.append(text.slice(last));
    node.replaceWith(frag);
  }
}

/* Entry pages: list the keywords found in the text */
const kwBox=$('#entry-keywords');
if(kwBox&&content){
  const seen=new Map();
  for(const m of content.querySelectorAll('.entry-body .lore-mark, .entry-summary .lore-mark, .entry-attribution .lore-mark, .declared-keywords .lore-mark')){
    const key=m.dataset.entry||('missing:'+m.textContent.toLowerCase());
    if(m.dataset.entry===currentEntry||seen.has(key))continue;
    seen.set(key,m);
  }
  const declared=$('.declared-keywords');if(declared)declared.remove();
  if(seen.size){
    kwBox.replaceChildren();
    for(const [key,m] of seen){
      const e=m.dataset.entry&&dictionary.find(d=>d.slug===m.dataset.entry);
      const chip=makeMark(e?e.title:m.textContent,e||null,false);
      if(e)chip.href=e.url;
      kwBox.append(chip);
    }
  }else kwBox.replaceChildren(Object.assign(document.createElement('p'),{className:'note',textContent:'No keywords detected yet. Wrap important nouns in [[double brackets]] to mark them.'}));
}

/* Highlight toggle (remembered per viewer) */
const toggle=$('#lore-toggle');
const store={get(k){try{return localStorage.getItem(k)}catch(e){return null}},set(k,v){try{localStorage.setItem(k,v)}catch(e){}}};
function setHighlight(on){main.classList.toggle('lore-off',!on);toggle.textContent=on?'Turn highlighting off':'Turn highlighting on';toggle.setAttribute('aria-pressed',String(on));}
if(toggle&&main){
  setHighlight(store.get('lore-highlight')!=='off');
  toggle.addEventListener('click',()=>{const on=main.classList.contains('lore-off');setHighlight(on);store.set('lore-highlight',on?'on':'off');});
}

/* ---------- 4. Ask the Story Bible ---------- */
const form=$('#bible-search-form'),input=$('#bible-query'),results=$('#bible-results');
const stop=new Set('a an and are as at be been but by can could did do does for from had has have how i in into is it its of on or our should so than that the their them there these they this to was were what when where which who why will with would you your we he she his her if more much'.split(' '));
const aliasWords={worm:'wyrm',worms:'wyrm',souls:'soul',siphoned:'siphon',siphoning:'siphon',contracts:'contract',stewards:'steward',ancestors:'ancestor',kingdoms:'kingdom',transmogrified:'transmogrification',transmogrify:'transmogrification',manifested:'manifestation',manifest:'manifestation',spirits:'spiritus'};
const terms=str=>[...new Set((str.toLowerCase().match(/[a-z0-9]+/g)||[]).map(x=>aliasWords[x]||x).filter(x=>x.length>2&&!stop.has(x)))];
let indexPromise=null;
function passagesFrom(root,page){
  const out=[];let active=page.title;
  const isArchive=page.section==='archive'||page.section==='sources';
  eachPassage(root,(el,i,isHeading,text)=>{
    if(isHeading){active=norm(el.textContent);return;}
    if(el.closest('aside,.breadcrumb,.pager'))return;
    out.push({text:norm(text.replace(explicitRe,(m,a,b)=>b||a)),context:page.title+' '+active,heading:active,title:page.title,url:page.url+'#'+el.id,archive:isArchive});
  });
  return out;
}
function buildIndex(){
  if(indexPromise)return indexPromise;
  const here=document.body.dataset.pageUrl;
  indexPromise=Promise.all(sitePages.map(page=>{
    if(page.url===here&&content){
      // Live page: ids were assigned before highlighting, so they match a fresh copy.
      return Promise.resolve(passagesFrom(content,page));
    }
    return fetch(page.url).then(r=>r.ok?r.text():'').then(html=>{
      const doc=new DOMParser().parseFromString(html,'text/html');
      const root=doc.querySelector('.page-content');
      return root?passagesFrom(root,page):[];
    }).catch(()=>[]);
  })).then(list=>list.flat());
  return indexPromise;
}
function score(entry,query){const q=terms(query),set=new Set(terms(entry.text)),hs=new Set(terms(entry.context));let hits=0,s=0;
  for(const w of q){if(set.has(w)||hs.has(w)){hits++;s+=set.has(w)?3:0;s+=hs.has(w)?5:0;}}
  if(!hits)return 0;s+=hits/q.length*9;if(hits<Math.min(2,q.length))s-=9;if(entry.archive)s-=3;return s;}
function excerpt(text,query){const q=terms(query),sentences=text.match(/[^.!?\n]+[.!?]?/g)||[text];let best=sentences[0],value=-1;
  for(const sentence of sentences){const st=new Set(terms(sentence));const v=q.reduce((n,w)=>n+(st.has(w)?1:0),0);if(v>value){best=sentence;value=v;}}
  best=norm(best);return best.length>420?best.slice(0,417)+'…':best;}
const el=(tag,txt,cls)=>{const n=document.createElement(tag);n.textContent=txt;if(cls)n.className=cls;return n;};
if(form){
  input.addEventListener('focus',()=>{buildIndex();},{once:true});
  form.addEventListener('submit',async event=>{
    event.preventDefault();results.replaceChildren();
    const query=input.value.trim();if(!query)return;
    const q=terms(query);if(!q.length){results.append(el('p','Please enter a more specific question.'));return;}
    results.append(el('p','Searching the Story Bible…','note'));
    const index=await buildIndex();results.replaceChildren();
    const ranked=index.map(e=>({e,s:score(e,query)})).filter(r=>r.s>0).sort((a,b)=>b.s-a.s);
    const top=ranked[0];
    const matched=top&&top.s>=10&&q.filter(w=>new Set([...terms(top.e.text),...terms(top.e.context)]).has(w)).length>=Math.min(2,q.length);
    if(!matched){
      results.append(el('p','Unanswered — No apparent answer found in the Story Bible.','answer-status'));
      results.append(el('p','This search cannot establish whether the answer exists in other sources. Try different terms or check the continuity audit.','source-note'));
      if(location.protocol==='file:')results.append(el('p','Note: opened as a local file, so only this page could be searched. Use the published site (or the original single-file bible in legacy/) for full search.','source-note'));
      return;
    }
    results.append(el('p','Possible matching passages (verify the cited context):','answer-status'));
    const used=new Set();let shown=0;
    for(const {e} of ranked){
      if(shown>=5)break;if(used.has(e.text))continue;used.add(e.text);shown++;
      const article=document.createElement('article');
      const a=document.createElement('a');a.href=e.url;a.textContent=e.title+(e.heading&&e.heading!==e.title?' › '+e.heading:'')+' — Jump to passage';
      article.append(a,el('p',excerpt(e.text,query)),el('p',e.archive?'Historical/source material — check current canon for superseding decisions.':'Bible excerpt — read surrounding context before treating it as a definitive answer.','source-note'));
      results.append(article);
    }
  });
}

/* ---------- 5. Return to reading position when a utility panel closes ---------- */
const readingPositions=new WeakMap();
const utilityPanels=[...document.querySelectorAll('details.utility-panel')];
let restoring=false;
const isInsideTool=n=>!!(n&&n.closest&&n.closest('details.utility-panel'));
function saveReadingPosition(panel){if(!panel||panel.open||readingPositions.has(panel))return;readingPositions.set(panel,{x:window.scrollX,y:window.scrollY,hash:location.hash});}
function panelFor(target){return target.matches('details.utility-panel')?target:target.closest('details.utility-panel');}
document.addEventListener('click',event=>{
  const link=event.target.closest('a[href^="#"]');if(!link)return;
  const target=document.getElementById(decodeURIComponent(link.getAttribute('href').slice(1)));if(!target)return;
  const panel=panelFor(target);if(!panel)return;
  if(!isInsideTool(link))saveReadingPosition(panel);
  panel.open=true;
  if(link.dataset.openPanel==='assistant-panel')setTimeout(()=>input&&input.focus({preventScroll:true}),50);
},true);
for(const panel of utilityPanels){
  panel.addEventListener('toggle',()=>{
    if(panel.open)return;
    const saved=readingPositions.get(panel);if(!saved||restoring)return;
    readingPositions.delete(panel);restoring=true;
    if(location.hash!==saved.hash)history.replaceState(null,'',location.pathname+location.search+saved.hash);
    requestAnimationFrame(()=>requestAnimationFrame(()=>{window.scrollTo({left:saved.x,top:saved.y,behavior:'instant'});restoring=false;}));
  });
}
function openFromHash(){const id=decodeURIComponent(location.hash.slice(1));if(!id)return;const t=document.getElementById(id);if(!t)return;const p=panelFor(t);if(p)p.open=true;}
openFromHash();window.addEventListener('hashchange',openFromHash);
/* Keyboard access for "missing" keyword marks */
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.classList&&e.target.classList.contains('lore-missing'))alert(e.target.title);});
})();
